package main

import (
	"flag"
	"fmt"
	"os"
)

func main() {
	n := flag.Int("n", 10, "lines per file")
	verbose := flag.Bool("v", false, "print each processed file")
	flag.Parse()
	for _, p := range flag.Args() {
		if _, err := os.Stat(p); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		if *verbose {
			fmt.Println(p)
		}
	}
	fmt.Println(*n, len(flag.Args()))
}
